"""Pydantic models for recommended actions generated by the Action Agent."""
from __future__ import annotations

import uuid
from datetime import datetime
from enum import Enum
from typing import Any, Dict, List, Optional

from pydantic import BaseModel, Field


class ActionType(str, Enum):
    DISCOUNT = "DISCOUNT"
    RECIPE = "RECIPE"
    DONATE = "DONATE"
    ALERT = "ALERT"
    COMPOST = "COMPOST"


class ActionPriority(str, Enum):
    URGENT = "URGENT"
    HIGH = "HIGH"
    MEDIUM = "MEDIUM"


class ActionStatus(str, Enum):
    pending = "pending"
    accepted = "accepted"
    completed = "completed"
    dismissed = "dismissed"


class EstimatedSavings(BaseModel):
    """Projected savings for an action."""

    money_usd: float = Field(0.0, ge=0)
    food_kg: float = Field(0.0, ge=0)
    co2_kg: float = Field(0.0, ge=0)
    meals_equivalent: int = Field(0, ge=0)


class ActionItem(BaseModel):
    """A single recommended action for reducing food waste."""

    id: str = Field(default_factory=lambda: str(uuid.uuid4()))
    type: ActionType
    priority: ActionPriority
    target_items: List[str] = Field(default_factory=list, description="Item IDs this action targets")
    title: str
    description: str
    details: Dict[str, Any] = Field(default_factory=dict)
    estimated_savings: EstimatedSavings = Field(default_factory=EstimatedSavings)
    status: ActionStatus = ActionStatus.pending
    created_at: datetime = Field(default_factory=datetime.utcnow)
    completed_at: Optional[datetime] = None


class ActionsResponse(BaseModel):
    """Response envelope for the /actions endpoint."""

    actions: List[ActionItem]
    total: int


class ChatRequest(BaseModel):
    """Request body for the conversational /actions/ask endpoint."""

    question: str = Field(..., min_length=1, max_length=2000)


class ChatResponse(BaseModel):
    """Response from the AI chat assistant."""

    answer: str
    suggested_actions: List[str] = Field(default_factory=list)
